package com.yeyamo_mobile.api.culture_service.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="culture_consent_declarations")public class CultureConsentDeclaration{public enum Action{DECLARED,WITHDRAWN}@Id private UUID id;@Column(name="submission_id",nullable=false)private UUID submissionId;@Column(name="declared_by",nullable=false)private String declaredBy;@Column(name="other_person_recorded",nullable=false)private boolean otherPersonRecorded;@Column(name="consent_confirmed",nullable=false)private boolean consentConfirmed;@Column(name="anonymized",nullable=false)private boolean anonymized;@Column(name="person_name")private String personName;@Enumerated(EnumType.STRING)@Column(nullable=false)private Action action;@Column(name="created_at",nullable=false)private Instant createdAt;protected CultureConsentDeclaration(){}public static CultureConsentDeclaration declared(UUID submission,String actor,boolean other,boolean confirmed,boolean anonymous,String name){CultureConsentDeclaration c=new CultureConsentDeclaration();c.id=UUID.randomUUID();c.submissionId=submission;c.declaredBy=actor;c.otherPersonRecorded=other;c.consentConfirmed=confirmed;c.anonymized=anonymous;c.personName=anonymous?null:name;c.action=Action.DECLARED;c.createdAt=Instant.now();return c;}public static CultureConsentDeclaration withdrawn(UUID submission,String actor){return declared(submission,actor,false,false,true,null).withAction(Action.WITHDRAWN);}private CultureConsentDeclaration withAction(Action value){action=value;return this;}}
